SELECT

    rpfp.PRODUUID produuid,
    rpfp.PROD_ID prodId,
    rpfp.PROFIT_TYPE profitType,
    rpfp.PROD_SERIES prodSeries,
    rpfp.ISSUE_TYPE issueType,
    rpfp.DATA_STATUS dataStatus,
    rpfp.RAISE_TYPE raiseType,
    rpfp.RAISE_VDATE raiseVdate,
    rpfp.RAISE_ENDDATE raiseEnddate,
    rpfp.VDATE vdate,
    rpfp.CCY ccy,
    rpfp.PROFIT_FLAG profitFlag

FROM REP_PROD_FILE_PRODINFO rpfp



	        #{prodId,jdbcType=VARCHAR}




	        #{profitType,jdbcType=VARCHAR}




	        #{prodSeries,jdbcType=VARCHAR}




	        #{issueType,jdbcType=VARCHAR}




	        #{dataStatus,jdbcType=VARCHAR}




	        #{raiseType,jdbcType=VARCHAR}




	        #{ccy,jdbcType=VARCHAR}




	        #{profitFlag,jdbcType=VARCHAR}



        AND DATE_FORMAT(rpfp.RAISE_VDATE,'%Y-%m-%d') >= #{raiseVdateStr,jdbcType=VARCHAR}


        AND DATE_FORMAT(rpfp.RAISE_VDATE,'%Y-%m-%d') <= #{raiseVdateEnd,jdbcType=VARCHAR}


        AND DATE_FORMAT(rpfp.RAISE_ENDDATE,'%Y-%m-%d') >= #{raiseEnddateStr,jdbcType=VARCHAR}


        AND DATE_FORMAT(rpfp.RAISE_ENDDATE,'%Y-%m-%d') <= #{raiseEnddateEnd,jdbcType=VARCHAR}


        AND DATE_FORMAT(rpfp.VDATE,'%Y-%m-%d') >= #{vdateStr,jdbcType=VARCHAR}


        AND DATE_FORMAT(rpfp.VDATE,'%Y-%m-%d') <= #{vdateEnd,jdbcType=VARCHAR}

